29	// ScalingContext defines the generalized context that holds all necessary data for scaling calculations.
30	// This is the single source of truth for all scaling configuration, extracted per-PodAutoscaler.
31	type ScalingContext interface {
32		GetTargetValueForMetric(metricName string) (float64, bool)
33		GetUpFluctuationTolerance() float64
34		GetDownFluctuationTolerance() float64
35		GetMaxScaleUpRate() float64
36		GetMaxScaleDownRate() float64
37		GetCurrentUsePerPod() float64
38		SetCurrentUsePerPod(float64)
39		UpdateByPaTypes(pa *autoscalingv1alpha1.PodAutoscaler) error
40		GetMinReplicas() int32
41		GetMaxReplicas() int32
42		GetStableValue() float64
43		SetStableValue(float64)
44		GetPanicValue() float64
45		SetPanicValue(float64)
46		SetActivationScale(value int32)
47		GetActivationScale() int32
48		GetPanicThreshold() float64
49		GetInPanicMode() bool
50		SetInPanicMode(bool)
51		GetMaxPanicPods() int32
52		SetMaxPanicPods(int32)
53		GetScaleUpCooldownWindow() time.Duration
54		GetScaleDownCooldownWindow() time.Duration
55		GetScaleToZero() bool
56	}
57	
58	// baseScalingContext provides a base implementation of the ScalingContext interface.
59	type baseScalingContext struct {
60		// Maximum rate at which to scale up
61		MaxScaleUpRate float64
62		// Maximum rate at which to scale down, a value of 2.5 means the count can reduce to at most 2.5 times less than the current value in one step.
63		MaxScaleDownRate float64
64		// The current use per pod.
65		currentUsePerPod float64
66		// The minimum number of replicas to which the target can be scaled down.
67		MinReplicas int32
68		// The maximum number of replicas to which the target can be scaled up
69		MaxReplicas int32
70		// Tolerance for fluctuations in metrics before scaling up
71		UpFluctuationTolerance float64
72		// Tolerance for fluctuations in metrics before scaling down
73		DownFluctuationTolerance float64
74		// Cooldown window for scale-up decisions (prevents rapid scale-ups)
75		ScaleUpCooldownWindow time.Duration
76		// Cooldown window for scale-down decisions (prevents rapid scale-downs)
77		ScaleDownCooldownWindow time.Duration
78		// Scale to zero flag
79		ScaleToZero bool
80		// Panic threshold for KPA
81		PanicThreshold float64
82	
83		// Stable and Panic values
84		StableValue float64
85		PanicValue  float64
86	
87		// Panic mode state
88		InPanicMode bool
89		// MetricTargets used to store multiple metrics
90		MetricTargets map[string]MetricTarget // key: metric name (e.g., "cpu", "gpu_cache_usage_perc")
91	}
92	
93	type MetricTarget struct {
94		// The value of scaling metric per pod that we target to maintain.
95		TargetValue float64
96		// The total value of scaling metric that a pod can maintain.
97		TotalValue float64
98		// The metric used for scaling, i.e. CPU, Memory, QPS.
99		ScalingMetric string
100		MetricType    autoscalingv1alpha1.MetricSourceType
101	}
102	
103	var _ ScalingContext = (*baseScalingContext)(nil)
104	
105	// NewBaseScalingContext creates a new instance of BaseScalingContext with default values.
106	func NewBaseScalingContext() *baseScalingContext {
107		return &baseScalingContext{
108			MaxScaleUpRate:           2,                 // Scale up rate of 200%, allowing rapid scaling
109			MaxScaleDownRate:         2,                 // Scale down rate of 50%, for more gradual reduction
110			UpFluctuationTolerance:   0.1,               // Default 10% tolerance for scale-up
111			DownFluctuationTolerance: 0.1,               // Default 10% tolerance for scale-down
112			ScaleUpCooldownWindow:    0 * time.Second,   // Default: no cooldown for scale-up
113			ScaleDownCooldownWindow:  300 * time.Second, // Default: 5 minutes cooldown for scale-down
114			ScaleToZero:              false,             // Default: do not scale to zero
115			PanicThreshold:           2.0,               // Default panic threshold for KPA
116			MetricTargets:            make(map[string]MetricTarget),
117		}
118	}
119	
120	// annotationParser is a function type for parsing annotation values
121	type annotationParser func(b *baseScalingContext, value string) error
122	
123	// annotationParsers maps annotation keys to their parsing functions
124	var annotationParsers = map[string]annotationParser{
125		types.MaxScaleUpRateLabel: func(b *baseScalingContext, value string) error {
126			v, err := strconv.ParseFloat(value, 64)
127			if err == nil {
128				b.MaxScaleUpRate = v
129			}
130			return err
131		},
132		types.MaxScaleDownRateLabel: func(b *baseScalingContext, value string) error {
133			v, err := strconv.ParseFloat(value, 64)
134			if err == nil {
135				b.MaxScaleDownRate = v
136			}
137			return err
138		},
139		types.ScaleUpToleranceLabel: func(b *baseScalingContext, value string) error {
140			v, err := strconv.ParseFloat(value, 64)
141			if err == nil {
142				b.UpFluctuationTolerance = v
143			}
144			return err
145		},
146		types.ScaleDownToleranceLabel: func(b *baseScalingContext, value string) error {
147			v, err := strconv.ParseFloat(value, 64)
148			if err == nil {
149				b.DownFluctuationTolerance = v
150			}
151			return err
152		},
153		types.PanicThresholdLabel: func(b *baseScalingContext, value string) error {
154			v, err := strconv.ParseFloat(value, 64)
155			if err == nil {
156				b.PanicThreshold = v
157			}
158			return err
159		},
160		types.ScaleUpCooldownWindowLabel: func(b *baseScalingContext, value string) error {
161			v, err := time.ParseDuration(value)
162			if err == nil {
163				b.ScaleUpCooldownWindow = v
164			}
165			return err
166		},
167		types.ScaleDownCooldownWindowLabel: func(b *baseScalingContext, value string) error {
168			v, err := time.ParseDuration(value)
169			if err == nil {
170				b.ScaleDownCooldownWindow = v
171			}
172			return err
173		},
174		types.ScaleToZeroLabel: func(b *baseScalingContext, value string) error {
175			v, err := strconv.ParseBool(value)
176			if err == nil {
177				b.ScaleToZero = v
178			}
179			return err
180		},
181	}
182	
183	// UpdateByPaTypes should be invoked in any scaling context that embeds BaseScalingContext.
184	func (b *baseScalingContext) UpdateByPaTypes(pa *autoscalingv1alpha1.PodAutoscaler) error {
185		for _, ms := range pa.Spec.MetricsSources {
186			targetValue, err := strconv.ParseFloat(ms.TargetValue, 64)
187			if err != nil {
188				klog.ErrorS(err, "Failed to parse target value", "metric", ms.TargetMetric, "value", ms.TargetValue)
189				return fmt.Errorf("invalid targetValue for metric %q: %w", ms.TargetMetric, err)
190			}
191			if targetValue <= 0 {
192				return fmt.Errorf("targetValue for metric %q must be greater than 0, got %f", ms.TargetMetric, targetValue)
193			}
194	
195			b.MetricTargets[ms.TargetMetric] = MetricTarget{
196				TargetValue:   targetValue,
197				TotalValue:    100.0,
198				ScalingMetric: ms.TargetMetric,
199				MetricType:    ms.MetricSourceType,
200			}
201		}
202	
203		// Parse annotations using registered parsers
204		for key, value := range pa.Annotations {
205			if parser, ok := annotationParsers[key]; ok {
206				if err := parser(b, value); err != nil {
207					return err
208				}
209			}
210		}
211		return nil
212	}
213	
214	func (b *baseScalingContext) SetCurrentUsePerPod(value float64) {
215		b.currentUsePerPod = value
216	}
217	
218	func (b *baseScalingContext) SetMinReplicas(minReplicas int32) {
219		b.MinReplicas = minReplicas
220	}
