	if target, ok := b.MetricTargets[metricName]; ok {
		return target.TargetValue, true
	}
	return 0, false
}

func (b *baseScalingContext) GetScalingTolerance() (up float64, down float64) {
	return b.MaxScaleUpRate, b.MaxScaleDownRate
}

func (b *baseScalingContext) GetMinReplicas() int32 {
	return b.MinReplicas
}

func (b *baseScalingContext) GetMaxReplicas() int32 {
	return b.MaxReplicas
}

func (b *baseScalingContext) GetStableValue() float64 {
	return b.StableValue
}

func (b *baseScalingContext) SetStableValue(value float64) {
	b.StableValue = value
}

func (b *baseScalingContext) GetPanicValue() float64 {
	return b.PanicValue
}

func (b *baseScalingContext) SetPanicValue(value float64) {
	b.PanicValue = value
}

func (b *baseScalingContext) GetActivationScale() int32 {
	return 1
}

func (b *baseScalingContext) SetActivationScale(value int32) {
	// No-op in base implementation
}

func (b *baseScalingContext) GetPanicThreshold() float64 {
	return b.PanicThreshold
}

func (b *baseScalingContext) GetInPanicMode() bool {
	return b.InPanicMode
}

func (b *baseScalingContext) SetInPanicMode(inPanic bool) {
	b.InPanicMode = inPanic
}

func (b *baseScalingContext) GetMaxPanicPods() int32 {
	return 0
}

func (b *baseScalingContext) SetMaxPanicPods(pods int32) {
	// No-op in base implementation
}

func (b *baseScalingContext) GetScaleUpCooldownWindow() time.Duration {
	return b.ScaleUpCooldownWindow
}

func (b *baseScalingContext) GetScaleDownCooldownWindow() time.Duration {
	return b.ScaleDownCooldownWindow
}

func (b *baseScalingContext) GetScaleToZero() bool {
	return b.ScaleToZero
}

// executeScalingPipeline contains the common scaling logic for replica computation
func (a *DefaultAutoScaler) executeScalingPipeline(
	ctx context.Context,
	request ReplicaComputeRequest,
	metricKey types.MetricKey,
	metricSource autoscalingv1alpha1.MetricSource,
	algo algorithm.ScalingAlgorithm,
) (*algorithm.ScalingRecommendation, error) {
	workloadKey := fmt.Sprintf("%s/%s", request.PodAutoscaler.Namespace, request.PodAutoscaler.Name)

	// Step 1: Collect metrics
	collectionSpec := types.CollectionSpec{
		Namespace:    metricKey.Namespace,
		TargetName:   metricKey.Name,
		MetricName:   metricKey.MetricName,
		MetricSource: metricSource,
		Pods:         request.Pods,
		Timestamp:    request.Timestamp,
	}

	klog.InfoS("Collecting metrics", "source", workloadKey, "pods", len(request.Pods))
	snapshot, err := metrics.CollectMetrics(ctx, collectionSpec, a.factory)
	if err != nil {
		return nil, fmt.Errorf("failed to collect metrics for %s: %w", workloadKey, err)
	}

	// Use scaling context from request (single source of truth)
	scalingContext := request.ScalingContext

	// Step 2: Process and aggregate metrics
	stableWindow, panicWindow := metricWindowDurations(request.PodAutoscaler)
	if err := a.metricsClient.ConfigureMetricWindows(metricKey, stableWindow, panicWindow); err != nil {
		return nil, fmt.Errorf("failed to configure metric windows for %s: %w", workloadKey, err)
	}

	klog.InfoS("Processing metrics snapshot", "source", workloadKey, "healthy metrics pods", len(snapshot.Values), "values", snapshot.Values)
	if err := a.aggregator.ProcessSnapshot(metricKey, snapshot); err != nil {
		return nil, fmt.Errorf("failed to process metrics snapshot for %s: %w", workloadKey, err)
	}
	// Use the full metricKey with PaNamespace and PaName for proper multi-tenancy
	aggregatedMetrics, err := a.aggregator.GetAggregatedMetrics(metricKey, request.Timestamp)
	if err != nil {
		return nil, fmt.Errorf("failed to get aggregated metrics for %s %s: %w", workloadKey, metricKey, err)
	}

	// Step 3: Enhance confidence with pod count awareness
	// TODO: enable confidence and pod count later
	//podCount := len(request.Pods)
	//if podCount > 0 {
	//	// Simple pod-aware confidence enhancement
	//	// More pods = higher confidence (diminishing returns)
	//	podConfidenceFactor := minFloat64(1.0, float64(podCount)/5.0)
	//	aggregatedMetrics.Confidence = minFloat64(1.0, aggregatedMetrics.Confidence*0.7+podConfidenceFactor*0.3)
	//}

	klog.InfoS("Metrics aggregated",
		"averageValue", aggregatedMetrics.StableValue,
		"trend", aggregatedMetrics.Trend,
		"confidence", aggregatedMetrics.Confidence,
		"podCount", len(request.Pods))

	// Step 4: Make scaling decision
	scalingRequest := algorithm.ScalingRequest{
		Target: types.ScaleTarget{
			Namespace:  request.PodAutoscaler.Namespace,
			Name:       request.PodAutoscaler.Spec.ScaleTargetRef.Name,
			Kind:       request.PodAutoscaler.Spec.ScaleTargetRef.Kind,
			APIVersion: request.PodAutoscaler.Spec.ScaleTargetRef.APIVersion,
			MetricKey:  metricKey,
		},
		CurrentReplicas:   request.CurrentReplicas,
		AggregatedMetrics: aggregatedMetrics,
		ScalingContext:    scalingContext,
		Timestamp:         request.Timestamp,
	}

	klog.InfoS("Computing scaling recommendation", "source", workloadKey,
		"algorithm", algo.GetAlgorithmType())
	recommendation, err := algo.ComputeRecommendation(ctx, scalingRequest)
	if err != nil {
		return nil, fmt.Errorf("failed to compute scaling recommendation for %s: %w", workloadKey, err)
	}
	klog.InfoS("Scaling recommendation computed",
		"source", workloadKey,
		"algorithm", algo.GetAlgorithmType(),
		"recommendation", recommendation)

	return recommendation, nil
}

func metricWindowDurations(pa autoscalingv1alpha1.PodAutoscaler) (time.Duration, time.Duration) {
	stableWindow := metrics.DefaultStableWindowDuration
	if pa.Spec.ObserveWindowSeconds != nil {
		stableWindow = time.Duration(*pa.Spec.ObserveWindowSeconds) * time.Second
	}

	panicWindow := metrics.DefaultPanicWindowDuration
	if pa.Spec.PanicWindowSeconds != nil {
		panicWindow = time.Duration(*pa.Spec.PanicWindowSeconds) * time.Second
	}

	return stableWindow, panicWindow
}

// Helper methods

	// SubTargetSelector selects a sub-component within the target resource
	// For StormService/RoleSet: selects a role by roleName
	// If not specified, scales the entire resource
	// +optional
	SubTargetSelector *SubTargetSelector `json:"subTargetSelector,omitempty"`

	//// PodSelector allows for more flexible selection of pods to scale based on labels.
	//PodSelector *metav1.LabelSelector `json:"podSelector,omitempty"`

	// MinReplicas is the minimum number of replicas to which the target can be scaled down.
	// +optional
	MinReplicas *int32 `json:"minReplicas,omitempty"`

	// MaxReplicas is the maximum number of replicas to which the target can be scaled up.
	// It cannot be less than minReplicas
	MaxReplicas int32 `json:"maxReplicas"`

	// MetricsSources defines a list of sources from which metrics are collected to make scaling decisions.
	// +kubebuilder:validation:MinItems=1
	MetricsSources []MetricSource `json:"metricsSources,omitempty"`

	// ObserveWindowSeconds controls how much recent metric history is used for stable scaling decisions.
	// If unset, the autoscaler uses its internal default.
	// +optional
	// +kubebuilder:validation:Minimum=1
	// +kubebuilder:validation:Maximum=3600
	ObserveWindowSeconds *int64 `json:"observeWindowSeconds,omitempty"`

	// PanicWindowSeconds controls the short metric window used by KPA panic-mode decisions.
	// If unset, the autoscaler uses its internal default.
	// +optional
	// +kubebuilder:validation:Minimum=1
	// +kubebuilder:validation:Maximum=3600
	PanicWindowSeconds *int64 `json:"panicWindowSeconds,omitempty"`

	// ScalingStrategy defines the strategy to use for scaling.
	// +kubebuilder:validation:Enum={HPA,KPA,APA}
	ScalingStrategy ScalingStrategyType `json:"scalingStrategy"`
}

// SubTargetSelector identifies a sub-component within the scale target
type SubTargetSelector struct {
	// RoleName selects a role within StormService or RoleSet
	// +optional
	RoleName string `json:"roleName,omitempty"`
}

// ScalingStrategyType defines the type for scaling strategies.
type ScalingStrategyType string

const (
	// HPA represents the Kubernetes native Horizontal Pod Autoscaler.
	HPA ScalingStrategyType = "HPA"

	// KPA represents the KNative Pod Autoscaling Algorithm
	KPA ScalingStrategyType = "KPA"

	// APA represents the AiBrix Pod Autoscaling Algorithm
	APA ScalingStrategyType = "APA"
)

type MetricSourceType string

const (
	// POD fetches metrics from individual pod endpoints (http[s]://pod_ip:port/path)
	POD MetricSourceType = "pod"
	// RESOURCE fetches metrics from Kubernetes resource metrics API (cpu, memory)
	RESOURCE MetricSourceType = "resource"
	// CUSTOM fetches metrics from Kubernetes custom metrics API
	CUSTOM MetricSourceType = "custom"
	// EXTERNAL fetches metrics from external services like gpu-optimizer (e.g., gpu-optimizer.aibrix-system.svc.cluster.local:8080)
	EXTERNAL MetricSourceType = "external"
	// DOMAIN is deprecated, use EXTERNAL instead
	// +deprecated
	DOMAIN MetricSourceType = "domain"
)

type ProtocolType string

const (
	HTTP  ProtocolType = "http"
	HTTPS ProtocolType = "https"
)

// MetricSource defines an endpoint and path from which metrics are collected.
type MetricSource struct {
	// Specifies how to fetch metrics: from individual pods, Kubernetes APIs, or external services
	// +kubebuilder:validation:Enum={pod,resource,custom,external,domain}
	MetricSourceType MetricSourceType `json:"metricSourceType"`
	// Protocol for metric collection. Required only for 'pod' and 'external' types.
	// +optional
	// +kubebuilder:validation:Enum={http,https}
	ProtocolType ProtocolType `json:"protocolType,omitempty"`
	// External service endpoint (e.g., gpu-optimizer.aibrix-system.svc.cluster.local)
	// +optional
	Endpoint string `json:"endpoint,omitempty"`
	// Path to metrics endpoint (e.g., /api/metrics/cpu)
	// +optional
	Path string `json:"path,omitempty"`
	// Port for pod-level metrics. Only used for 'pod' type.
	// +optional
	Port string `json:"port,omitempty"`
	// TargetMetric identifies the specific metric to monitor (e.g., kv_cache_utilization).
	TargetMetric string `json:"targetMetric"`
	// TargetValue sets the desired threshold for the metric (e.g., 50 for 50% utilization).
	TargetValue string `json:"targetValue"`
}

// ScalingDecision represents a single scaling decision made by the autoscaler
type ScalingDecision struct {
	// Timestamp when the scaling decision was made
	Timestamp metav1.Time `json:"timestamp"`
	// PreviousScale is the number of replicas before scaling
	PreviousScale int32 `json:"previousScale"`
	// NewScale is the number of replicas after scaling
	NewScale int32 `json:"newScale"`
	// Reason provides the explanation for the scaling decision
	Reason string `json:"reason"`
	// Success indicates whether the scaling operation succeeded
	Success bool `json:"success"`

