15	*/
16	
17	package types
18	
19	import (
20		"math"
21		"sort"
22		"sync"
23		"time"
24	)
25	
26	// AggregatedMetrics contains processed metrics data
27	type AggregatedMetrics struct {
28		MetricKey    MetricKey
29		CurrentValue float64
30		StableValue  float64
31		PanicValue   float64
32		Trend        float64
33		Confidence   float64
34		LastUpdated  time.Time
35	}
36	
37	// WindowStats represents statistics about a time window
38	type WindowStats struct {
39		DataPoints  int
40		Mean        float64
41		Variance    float64
42		StdDev      float64
43		Min         float64
44		Max         float64
45		LastUpdate  time.Time
46		WindowStart time.Time
47		WindowEnd   time.Time
48	}
49	
50	// MetricPoint represents a single metric measurement
51	type MetricPoint struct {
52		Timestamp time.Time
53		Value     float64
54	}
55	
56	// MetricHistory tracks historical metrics for trend analysis
57	type MetricHistory struct {
58		mu      sync.RWMutex
59		history []MetricPoint
60		maxAge  time.Duration
61	}
62	
63	// NewMetricHistory creates a new metric history tracker
64	func NewMetricHistory(maxAge time.Duration) *MetricHistory {
65		return &MetricHistory{
66			history: make([]MetricPoint, 0, 100),
67			maxAge:  maxAge,
68		}
69	}
70	
71	// Add adds a new metric point to history
72	func (h *MetricHistory) Add(value float64, timestamp time.Time) {
73		h.mu.Lock()
74		defer h.mu.Unlock()
75	
76		// Add new point
77		h.history = append(h.history, MetricPoint{
78			Timestamp: timestamp,
79			Value:     value,
80		})
81	
82		// Clean old points
83		cutoff := timestamp.Add(-h.maxAge)
84		validStart := 0
85		for i, point := range h.history {
86			if point.Timestamp.After(cutoff) {
87				validStart = i
88				break
89			}
90		}
91		if validStart > 0 {
92			h.history = h.history[validStart:]
93		}
94	}
95	
96	// GetStats calculates statistics for the history
97	func (h *MetricHistory) GetStats(now time.Time) WindowStats {
98		h.mu.RLock()
99		defer h.mu.RUnlock()
100	
101		if len(h.history) == 0 {
102			return WindowStats{
103				DataPoints:  0,
104				LastUpdate:  now,
105				WindowStart: now.Add(-h.maxAge),
106				WindowEnd:   now,
107			}
108		}
109	
110		// Calculate statistics
111		var sum, min, max float64
112		min = math.MaxFloat64
113		max = -math.MaxFloat64
114	
115		for _, point := range h.history {
116			sum += point.Value
117			if point.Value < min {
118				min = point.Value
119			}
120			if point.Value > max {
121				max = point.Value
122			}
123		}
124	
125		mean := sum / float64(len(h.history))
126	
127		// Calculate variance
128		var varianceSum float64
129		for _, point := range h.history {
130			diff := point.Value - mean
131			varianceSum += diff * diff
132		}
133		variance := varianceSum / float64(len(h.history))
134		stdDev := math.Sqrt(variance)
135	
136		return WindowStats{
137			DataPoints:  len(h.history),
138			Mean:        mean,
139			Variance:    variance,
140			StdDev:      stdDev,
141			Min:         min,
142			Max:         max,
143			LastUpdate:  now,
144			WindowStart: h.history[0].Timestamp,
145			WindowEnd:   h.history[len(h.history)-1].Timestamp,
146		}
147	}
148	
149	// TimeWindow manages a sliding window of metric values
150	type TimeWindow struct {
151		mu          sync.RWMutex
152		duration    time.Duration
153		granularity time.Duration
154		buckets     map[int64]float64
155		values      []float64
156	}
157	
158	// NewTimeWindow creates a new time window
159	func NewTimeWindow(duration, granularity time.Duration) *TimeWindow {
160		return &TimeWindow{
161			duration:    duration,
162			granularity: granularity,
163			buckets:     make(map[int64]float64),
164			values:      make([]float64, 0),
165		}
166	}
167	
168	// Duration returns the configured sliding window duration.
169	func (tw *TimeWindow) Duration() time.Duration {
170		tw.mu.RLock()
171		defer tw.mu.RUnlock()
172		return tw.duration
173	}
174	
175	// Record adds a value to the time window
176	func (tw *TimeWindow) Record(timestamp time.Time, value float64) {
177		tw.mu.Lock()
178		defer tw.mu.Unlock()
179	
180		// Bucket the timestamp
181		bucket := timestamp.UnixNano() / int64(tw.granularity)
182		tw.buckets[bucket] = value
183	
184		// Clean old buckets
185		cutoff := timestamp.Add(-tw.duration).UnixNano() / int64(tw.granularity)
186		for b := range tw.buckets {
187			if b < cutoff {
188				delete(tw.buckets, b)
189			}
190		}
191	
192		// Update values slice in time order for deterministic behavior
193		bucketKeys := make([]int64, 0, len(tw.buckets))
194		for b := range tw.buckets {
195			bucketKeys = append(bucketKeys, b)
196		}
197		sort.Slice(bucketKeys, func(i, j int) bool {
198			return bucketKeys[i] < bucketKeys[j]
199		})
200	
201		tw.values = make([]float64, 0, len(tw.buckets))
202		for _, b := range bucketKeys {
203			tw.values = append(tw.values, tw.buckets[b])
204		}
205	}
206	
207	// Size returns the number of data points in the window
208	func (tw *TimeWindow) Size() int {
209		tw.mu.RLock()
210		defer tw.mu.RUnlock()
211		return len(tw.values)
212	}
213	
214	// Avg returns the average value in the window
215	func (tw *TimeWindow) Avg() (float64, error) {
216		tw.mu.RLock()
217		defer tw.mu.RUnlock()
218	
219		if len(tw.values) == 0 {
220			return 0, nil
221		}
222	
223		var sum float64
224		for _, v := range tw.values {
225			sum += v
226		}
227		return sum / float64(len(tw.values)), nil
228	}
229	
230	// Min returns the minimum value in the window
231	func (tw *TimeWindow) Min() (float64, error) {
232		tw.mu.RLock()
233		defer tw.mu.RUnlock()
234	
235		if len(tw.values) == 0 {
236			return 0, nil
237		}
238	
239		min := tw.values[0]
240		for _, v := range tw.values[1:] {
241			if v < min {
242				min = v
243			}
244		}
245		return min, nil
246	}
247	
248	// Max returns the maximum value in the window
249	func (tw *TimeWindow) Max() (float64, error) {
250		tw.mu.RLock()
251		defer tw.mu.RUnlock()
252	
253		if len(tw.values) == 0 {
254			return 0, nil
255		}
256	
257		max := tw.values[0]
258		for _, v := range tw.values[1:] {
259			if v > max {
